PROCEDURE PP_CARGAR_DATOS IS
	vDOCU_CODIGO_OPER ADRE.STK_DOCUMENTO.DOCU_CODIGO_OPER%TYPE;
	vDOCU_TIPO_MOV 		ADRE.STK_DOCUMENTO.DOCU_TIPO_MOV%TYPE;
	vDOCU_NRO_DOC 		ADRE.STK_DOCUMENTO.DOCU_NRO_DOC%TYPE;
BEGIN

  :BENCA.S_USUARIO         := USER;
  :BENCA.S_FECHA           := TO_CHAR(SYSDATE, 'DD-MM-YYYY');

  :BENCA.S_DESC_EMPRESA    := :PARAMETER.P_DESC_EMPRESA;
  :BENCA.S_DESC_SUCURSAL   := :PARAMETER.P_DESC_SUCURSAL;
  :BENCA.S_DESC_PROGRAMA   := :PARAMETER.P_DESC_PROGRAMA;
  :BENCA.S_PROGRAMA        := :PARAMETER.P_PROGRAMA;

  :PARAMETER.P_MON_US      := FL_MON_US;
  :PARAMETER.P_CANT_DEC_US := FL_MON_DEC_IMP(:PARAMETER.P_MON_US);


  IF :PARAMETER.P_DOCU_CLAVE IS NOT NULL THEN
  	 BEGIN
  		SELECT DOCU_CODIGO_OPER,
			       DOCU_TIPO_MOV,
			       DOCU_NRO_DOC
			  INTO vDOCU_CODIGO_OPER,
			  		 vDOCU_TIPO_MOV,
			  		 vDOCU_NRO_DOC
			  FROM ADRE.STK_DOCUMENTO
			 WHERE DOCU_CLAVE = :PARAMETER.P_DOCU_CLAVE	;
		 EXCEPTION WHEN OTHERS THEN NULL;
  	 END;
     :BSEL.S_TIPO_MOV         := NVL(:PARAMETER.P_TIPO_MOV, vDOCU_TIPO_MOV);
     :BSEL.S_CODIGO_OPERACION := NVL(:PARAMETER.P_COD_OPER, vDOCU_CODIGO_OPER);
     :BSEL.S_NRO_DOC          := NVL(:PARAMETER.P_NRO_FACT, vDOCU_NRO_DOC);
     :BDOCU.DOCU_CLAVE        := :PARAMETER.P_DOCU_CLAVE; 
  END IF;


	SET_ITEM_PROPERTY('BDOCU.DOCU_SUC_AUX'        , DISPLAYED, PROPERTY_FALSE);
	SET_ITEM_PROPERTY('BDOCU.S_DESC_DOCU_SUC_AUX' , DISPLAYED, PROPERTY_FALSE);
	SET_ITEM_PROPERTY('BDOCU.DOCU_DEP_AUX'        , DISPLAYED, PROPERTY_FALSE);
	SET_ITEM_PROPERTY('BDOCU.S_DESC_DOCU_DEP_AUX' , DISPLAYED, PROPERTY_FALSE);		 

END;

PROCEDURE PP_CONSTRUIR_WHERE (V_WHERE IN OUT VARCHAR2,
                              V_SENTENCIA IN VARCHAR2,
                              V_CONDICION IN VARCHAR2) IS
BEGIN
  IF V_WHERE IS NULL THEN
    V_WHERE := V_SENTENCIA;
  ELSE
    V_WHERE := V_WHERE||' '||V_CONDICION||' '||V_SENTENCIA;
  END IF;
END;

PROCEDURE PP_FORMAT_MASK(miNomItem IN VARCHAR2, miCantDecimales IN NUMBER) IS
  miLongMax number; /* Longitud máxima */
  miDecimales VARCHAR2(10); /* Formato de decimales */
  miEnteros VARCHAR2(20); /* Formato de la parte entera */
  miItemId ITEM; /* Identificador del item */
  miNuevoFormato VARCHAR2(20); /* Nuevo formato de máscara */
  miCantMaxEnt NUMBER := 0; /* Cantidad máxima de enteros */
  miTotDecimales NUMBER := 0;
BEGIN
  miItemId := FIND_ITEM(miNomItem);
  IF Id_Null(miItemId) THEN
     PL_EXHIBIR_ERROR('No existe el item: '|| miNomItem);
  END IF;

  miDecimales := 'D0000';
  miEnteros   := '999G999G999G990';

  miLongMax := GET_ITEM_PROPERTY(miItemId,MAX_LENGTH);

  IF miCantDecimales > 0 THEN
     miTotDecimales := miCantDecimales + 1; /* +1 por el punto decimal */
  END IF;

  miCantMaxEnt := miLongMax - miCantDecimales - 1;
  miNuevoFormato := SUBSTR(miEnteros, 15 - miCantMaxEnt)|| SUBSTR(miDecimales, 1 ,miTotDecimales);
  IF SUBSTR(miNuevoFormato,1,1)='G' THEN
     /* el primer caracter de formato no debe ser 'G' */
     miNuevoFormato := SUBSTR(miEnteros, 15 - miCantMaxEnt + 1)|| SUBSTR(miDecimales, 1 ,miTotDecimales);
  END IF;
  SET_ITEM_PROPERTY(miItemId, FORMAT_MASK, miNuevoFormato);
END;

PROCEDURE PP_MOSTRAR_DESC_TIPO_MOV(TipoMov IN NUMBER,
                                   Validar IN VARCHAR2) IS

BEGIN

  SELECT TMOV_DESC
  INTO  :BSEL.S_DESC_TIPO_MOV
  FROM  GEN_TIPO_MOV
  WHERE TMOV_CODIGO = TipoMov;

  IF :PARAMETER.P_OPER = 'VENTAS' THEN
    DECLARE
      V_VARIABLE VARCHAR2(1):=NULL;
    BEGIN
      SELECT 'X'
        INTO V_VARIABLE
        FROM STK_CONFIGURACION
       WHERE TipoMov NOT IN (CONF_FACT_CO_EMIT, CONF_FACT_CR_EMIT,
                         CONF_NOTA_DB_EMIT, CONF_NOTA_CR_EMIT)
         AND CONF_EMPR = :PARAMETER.P_EMPRESA;
       PL_EXHIBIR_ERROR('Movimiento inhabilitado!.');
    EXCEPTION
      WHEN NO_DATA_FOUND THEN
        NULL;
    END;
  END IF;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
     :BSEL.S_DESC_TIPO_MOV := NULL;
     IF Validar = 'VALIDAR' THEN
       PL_EXHIBIR_ERROR('Tipo inexistente!');
     END IF;
END;

PROCEDURE PP_MOSTRAR_DESC_OPER(CodOper IN NUMBER,
                               Validar IN VARCHAR2) IS

BEGIN
  SELECT OPER_DESC
  INTO  :BSEL.S_DESC_OPER
  FROM  STK_OPERACION
  WHERE OPER_CODIGO = CodOper;

  IF :PARAMETER.P_OPER = 'VENTAS' THEN
    IF :BSEL.S_DESC_OPER <> 'VENTA' AND :BSEL.S_DESC_OPER <> 'DEV_VENTA' THEN
      PL_EXHIBIR_ERROR('Operacion inhabilitada');
    END IF;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
     :BSEL.S_DESC_OPER := NULL;
     IF Validar = 'VALIDAR' THEN
       PL_EXHIBIR_ERROR('Código operacion inexistente!');
     END IF;
END;

PROCEDURE PP_MOSTRAR_DESC_PROVEEDOR(Validar IN VARCHAR2) IS

BEGIN
  SELECT PROV_RAZON_SOCIAL
  INTO  :BSEL.S_NOMBRE
  FROM  FIN_PROVEEDOR
  WHERE PROV_CODIGO   = :BSEL.S_PROV_CLIE; 

EXCEPTION
  WHEN NO_DATA_FOUND THEN
     :BSEL.S_NOMBRE := NULL;
     IF Validar = 'VALIDAR' THEN
       PL_EXHIBIR_ERROR('Proveedor inexistente!');
     END IF;
END;

