BEGIN
  SELECT DPTO_DESC
  INTO  :BDOCU.S_DESC_DEPARTAMENTO
  FROM  GEN_DEPARTAMENTO
  WHERE DPTO_CODIGO  = :BDOCU.DOCU_DPTO;

