PROCEDURE PP_MOSTRAR_DESC_DEPOSITO(Sucursal IN NUMBER,Deposito IN NUMBER,CampoDisp IN VARCHAR2) IS
  RDEP STK_DEPOSITO%ROWTYPE;

BEGIN
  SELECT * INTO  RDEP
  FROM  "ADRE"."STK_DEPOSITO"
  WHERE DEP_EMPR  = :PARAMETER.P_EMPRESA
    AND DEP_SUC = Sucursal
    AND DEP_CODIGO = Deposito; 

  COPY(RDEP.DEP_DESC, CampoDisp);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
     COPY(NULL, CampoDisp);
END;

PROCEDURE PP_MOSTRAR_DESC_VENDEDOR(V_CODIGO IN NUMBER,
				   V_NOMBRE IN OUT VARCHAR2) IS

BEGIN
  SELECT EMPL_NOMBRE INTO V_NOMBRE
    FROM  PER_EMPLEADO
    WHERE EMPL_LEGAJO  = V_CODIGO;



EXCEPTION
