PROCEDURE PP_MOSTRAR_DESC_MONEDA IS
  RMON GEN_MONEDA%ROWTYPE;

BEGIN
  SELECT * INTO RMON
  FROM  GEN_MONEDA
  WHERE MON_CODIGO  = :BDOCU.W_MON;

  :BDOCU.S_MON_SIMBOLO := RMON.MON_SIMBOLO;
  :BDOCU.W_MON_DEC_IMP := RMON.MON_DEC_IMP;
EXCEPTION
