PROCEDURE PP_MOSTRAR_DESC_CLIENTE IS

BEGIN
  SELECT CLI_NOM
  INTO  :BSEL.S_NOMBRE
  FROM  FIN_CLIENTE
  WHERE CLI_CODIGO   = :BSEL.S_PROV_CLIE; 

EXCEPTION
