     :BSEL.S_NOMBRE := :BDOCU.DOCU_CLI_NOM;
END;

Procedure Check_Package_Failure IS
BEGIN
  IF NOT ( Form_Success ) THEN
    RAISE Form_Trigger_Failure;
  END IF;
END;

PROCEDURE Query_Master_Details(rel_id Relation,detail VARCHAR2) IS
  oldmsg VARCHAR2(2);  -- Old Message Level Setting
  reldef VARCHAR2(5);  -- Relation Deferred Setting
BEGIN
  --
  -- Initialize Local Variable(s)
  --
  reldef := Get_Relation_Property(rel_id, DEFERRED_COORDINATION);
  oldmsg := :System.Message_Level;
  --
  -- If NOT Deferred, Goto detail and execute the query.
  --
  IF reldef = 'FALSE' THEN
    Go_Block(detail);
    Check_Package_Failure;
    :System.Message_Level := '10';
    Execute_Query;
    :System.Message_Level := oldmsg;
  ELSE
    --
    -- Relation is deferred, mark the detail block as un-coordinated
    --
    Set_Block_Property(detail, COORDINATION_STATUS, NON_COORDINATED);
  END IF;




EXCEPTION
    WHEN Form_Trigger_Failure THEN
      :System.Message_Level := oldmsg;
      RAISE;
END Query_Master_Details;

PROCEDURE Clear_All_Master_Details IS
  mastblk  VARCHAR2(30);  -- Initial Master Block Cusing Coord
  coordop  VARCHAR2(30);  -- Operation Causing the Coord
  trigblk  VARCHAR2(30);  -- Cur Block On-Clear-Details Fires On
  startitm VARCHAR2(61);  -- Item in which cursor started
  frmstat  VARCHAR2(15);  -- Form Status
  curblk   VARCHAR2(30);  -- Current Block
  currel   VARCHAR2(30);  -- Current Relation
  curdtl   VARCHAR2(30);  -- Current Detail Block

  FUNCTION First_Changed_Block_Below(Master VARCHAR2)
  RETURN VARCHAR2 IS
    curblk VARCHAR2(30);  -- Current Block
    currel VARCHAR2(30);  -- Current Relation
    retblk VARCHAR2(30);  -- Return Block
  BEGIN
    --
    -- Initialize Local Vars
    --
    curblk := Master;
    currel := Get_Block_Property(curblk,  FIRST_MASTER_RELATION);
    --
    -- While there exists another relation for this block
    --
    WHILE currel IS NOT NULL LOOP
      --
      -- Get the name of the detail block
      --
      curblk := Get_Relation_Property(currel, DETAIL_NAME);
      --
      -- If this block has changes, return its name
      --
      IF ( Get_Block_Property(curblk, STATUS) IN('CHANGED','INSERT') ) THEN
        RETURN curblk;
      ELSE
        --
        -- No changes, recursively look for changed blocks below
        --
        retblk := First_Changed_Block_Below(curblk);
        --
        -- If some block below is changed, return its name
        --
        IF retblk IS NOT NULL THEN
          RETURN retblk;
        ELSE
          --
          -- Consider the next relation
          --
          currel := Get_Relation_Property(currel, NEXT_MASTER_RELATION);
        END IF;
      END IF;
    END LOOP;

    --
    -- No changed blocks were found
    --
    RETURN NULL;
  END First_Changed_Block_Below;

BEGIN
  --
  -- Init Local Vars
  --
  mastblk  := :System.Master_Block;
  coordop  := :System.Coordination_Operation;
  trigblk  := :System.Trigger_Block;
  startitm := :System.Trigger_Item;
  frmstat  := :System.Form_Status;

  --
  -- If the coordination operation is anything but CLEAR_RECORD or
  -- SYNCHRONIZE_BLOCKS, then continue checking.
  --
  IF coordop NOT IN ('CLEAR_RECORD', 'SYNCHRONIZE_BLOCKS') THEN
    --
    -- If we're processing the driving master block...
    --
    IF mastblk = trigblk THEN
      --
      -- If something in the form is changed, find the
      -- first changed block below the master
      --
      IF frmstat = 'CHANGED' THEN
        curblk := First_Changed_Block_Below(mastblk);
        --
        -- If we find a changed block below, go there
        -- and Ask to commit the changes.
        --
        IF curblk IS NOT NULL THEN
          Go_Block(curblk);
          Check_Package_Failure;
          Clear_Block(ASK_COMMIT);
          --
          -- If user cancels commit dialog, raise error
          --
          IF NOT ( :System.Form_Status = 'QUERY'
                   OR :System.Block_Status = 'NEW' ) THEN
            RAISE Form_Trigger_Failure;
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;

  --
  -- Clear all the detail blocks for this master without
  -- any further asking to commit.
  --
  currel := Get_Block_Property(trigblk, FIRST_MASTER_RELATION);
  WHILE currel IS NOT NULL LOOP
    curdtl := Get_Relation_Property(currel, DETAIL_NAME);
    IF Get_Block_Property(curdtl, STATUS) <> 'NEW'  THEN
      Go_Block(curdtl);
      Check_Package_Failure;
      Clear_Block(NO_VALIDATE);
      IF :System.Block_Status <> 'NEW' THEN
        RAISE Form_Trigger_Failure;
      END IF;
    END IF;
    currel := Get_Relation_Property(currel, NEXT_MASTER_RELATION);
  END LOOP;

  --
  -- Put cursor back where it started
  --
  IF :System.Cursor_Item <> startitm THEN
    Go_Item(startitm);
    Check_Package_Failure;
  END IF;

EXCEPTION
  WHEN Form_Trigger_Failure THEN
    IF :System.Cursor_Item <> startitm THEN
      Go_Item(startitm);
    END IF;
    RAISE;

END Clear_All_Master_Details;

FUNCTION FP_FORMAT_MASK(miNomItem IN VARCHAR2, miCantDecimales IN NUMBER)
RETURN VARCHAR2 IS
/* esta funcion la hice porque no funciona el GET_ITEM_PROPERTY para
    obtener el FORMAT_MASK de un item si es que el mismo se estableció
    programáticamente. Esta función es una pequeña variante de la
    procedure PP_FORMAT_MASK y a diferencia de ésta, devuelve el Formato en
    vez de establecerlo.
*/
  miLongMax number; /* Longitud máxima */
  miDecimales VARCHAR2(10); /* Formato de decimales */
  miEnteros VARCHAR2(20); /* Formato de la parte entera */
  miItemId ITEM; /* Identificador del item */
  miNuevoFormato VARCHAR2(20); /* Nuevo formato de máscara */
  miCantMaxEnt NUMBER := 0; /* Cantidad máxima de enteros */
  miTotDecimales NUMBER := 0;
BEGIN
  miItemId := FIND_ITEM(miNomItem);
  IF Id_Null(miItemId) THEN
     PL_EXHIBIR_ERROR('No existe el item: '|| miNomItem);
  END IF;

  miDecimales := 'D0000';
  miEnteros   := '999G999G999G990';

  miLongMax := GET_ITEM_PROPERTY(miItemId,MAX_LENGTH);

  IF miCantDecimales > 0 THEN
     miTotDecimales := miCantDecimales + 1; /* +1 por el punto decimal */
  END IF;

  miCantMaxEnt := miLongMax - miCantDecimales - 1;
  miNuevoFormato := SUBSTR(miEnteros, 15 - miCantMaxEnt)|| SUBSTR(miDecimales, 1 ,miTotDecimales);
  IF SUBSTR(miNuevoFormato,1,1)='G' THEN
     /* el primer caracter de formato no debe ser 'G' */
     miNuevoFormato := SUBSTR(miEnteros, 15 - miCantMaxEnt + 1)|| SUBSTR(miDecimales, 1 ,miTotDecimales);
  END IF;
  RETURN miNuevoFormato;
END;

PROCEDURE PP_MOSTRAR_COSTO IS
  V_COSTO_PROM_MON NUMBER;
BEGIN


 SELECT	
	  DECODE(AEP_COSTO_PROM_MON, 0 , NVL(AEP_COSTO_PROV, AEP_COSTO_PROM_MON), AEP_COSTO_PROM_MON) AEP_COSTO_PROM_MON 

   INTO V_COSTO_PROM_MON
    FROM STK_ART_EMPR_PERI
   WHERE AEP_PERIODO = :BDOCU.W_PERIODO
     AND AEP_EMPR = :BDOCU.DOCU_EMPR
     AND AEP_ART = :BDETA.DETA_ART;

  :BDETA.S_IMP_EXEN_MON := V_COSTO_PROM_MON;
  :BDETA.S_IMP_GRAV_MON := :BDETA.DETA_CANT * V_COSTO_PROM_MON;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
END;

PROCEDURE PP_DATOS_OPERACION IS
BEGIN
  SELECT OPER_IND_COSTO_VALOR
    INTO :BDOCU.W_IND_COSTO_VALOR
    FROM STK_OPERACION
   WHERE OPER_CODIGO = :BDOCU.DOCU_CODIGO_OPER;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    :BDOCU.W_IND_COSTO_VALOR := NULL;
END;

FUNCTION FP_DEVUELVE_NRO_FACT (CLAVE_STK_DOCUMENTO IN NUMBER) RETURN VARCHAR2 IS

V_FACTURA	varchar2(30) := 'NO REGISTRA VENTA'  ;

BEGIN


select docu_nro_doc
INTO  V_FACTURA
from stk_documento
where docu_clave = (select node_docu_clave
                   from fac_nota_devu
                   where node_doc_clave = (
                                           select doc_clave
                                           from fin_documento
                                           where doc_clave_stk = CLAVE_STK_DOCUMENTO));


RETURN V_FACTURA;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
			RETURN V_FACTURA;
  WHEN OTHERS THEN
      RETURN V_FACTURA;

END;

FUNCTION FP_DEVUELVE_NRO_SOLICITUD (CLAVE_STK_DOCUMENTO IN NUMBER) RETURN VARCHAR2 IS

V_SOLICITUD	varchar2(30) := 'NO REGISTRA SOLICITUD'  ;


BEGIN
			SELECT NODE_NUME
			INTO V_SOLICITUD
			FROM "ADRE"."FAC_NOTA_DEVU", "ADRE"."FIN_DOCUMENTO", "ADRE"."STK_DOCUMENTO"
			WHERE NODE_DOC_CLAVE = DOC_CLAVE -- FIN_DOCUMENTO
			AND DOC_CLAVE_STK    = DOCU_CLAVE -- STK_DOCUMENTO
			AND DOCU_CLAVE       = CLAVE_STK_DOCUMENTO ; --- CLAVE_DEL FORMULARIO


			RETURN 	V_SOLICITUD;

EXCEPTION
  WHEN NO_DATA_FOUND THEN
			RETURN V_SOLICITUD;
  WHEN OTHERS THEN
      RETURN V_SOLICITUD;
END;

PROCEDURE P_OBS_FIN_DOC  IS


V_OBS VARCHAR2(200);



BEGIN


SELECT DOC_OBS , ((DOC_CLAVE - 110) / 10000)  DOC_CLAVE_RESPALDO
INTO   :BDOCU.S_DOCU_OBS, :BSEL.W_CLAVE_RESPALDO
FROM   "ADRE"."FIN_DOCUMENTO"
WHERE  DOC_CLAVE_STK = :BDOCU.DOCU_CLAVE ;




EXCEPTION
	WHEN NO_DATA_FOUND THEN 
	 :BDOCU.S_DOCU_OBS          := NULL;
	 :BSEL.W_CLAVE_RESPALDO     := 1;--NULL;
	WHEN OTHERS THEN 
   :BDOCU.S_DOCU_OBS          := NULL;
	 :BSEL.W_CLAVE_RESPALDO     := 2;--NULL;


END;

PROCEDURE P_CLAVE_RESPALDO IS

V_WHERE VARCHAR2(80);
vCLAVE  NUMBER(14);
BEGIN
	:PARAMETER.P_DOCU_CLAVE := NULL;
	vClave                  := (:BSEL.W_CLAVE_RESPALDO * 10000) + (NVL(:PARAMETER.P_EMPRESA,1)*100) + 10 ;

	IF :BSEL.W_CLAVE_RESPALDO IS NOT NULL THEN

	  SELECT DOC_CLAVE_STK, DOC_NRO_DOC , 3 , DOC_TIPO_MOV
	  INTO :PARAMETER.P_DOCU_CLAVE , :BSEL.S_NRO_DOC, :BSEL.S_CODIGO_OPERACION , :BSEL.S_TIPO_MOV
    FROM "ADRE"."FIN_DOCUMENTO"
    WHERE DOC_CLAVE	=      vClave   ;

  END IF;   

    IF :PARAMETER.P_DOCU_CLAVE IS NOT NULL THEN        	
        V_WHERE := ' DOCU_CLAVE = '||:PARAMETER.P_DOCU_CLAVE||' AND DOCU_CODIGO_OPER = 3';
    END IF;

        /*
        || establecer la propiedad DEFAULT_WHERE del bloque BDOCU
        || y ejecutar la consulta
        */

        SET_BLOCK_PROPERTY('BDOCU', DEFAULT_WHERE, V_WHERE);
        GO_BLOCK('BDOCU');        
        EXECUTE_QUERY ; 	
	     :PARAMETER.P_DOCU_CLAVE := NULL;



   EXCEPTION
	 WHEN NO_DATA_FOUND THEN NULL;
   :PARAMETER.P_DOCU_CLAVE   := NULL; 
   :BSEL.S_NRO_DOC           := NULL;
   :BSEL.S_CODIGO_OPERACION  := NULL;
    NEXT_ITEM; 





END;

DECLARE
  errnum NUMBER       := ERROR_CODE;
  errtxt VARCHAR2(80) := ERROR_TEXT;
  errtyp VARCHAR2(3)  := ERROR_TYPE;
  dbmserrnum NUMBER := DBMS_ERROR_CODE;
  V_ALERT   NUMBER;
BEGIN
break;
  IF errnum    = 40200 THEN
    PL_EXHIBIR_ERROR('Dato no modificable!');
  ELSIF errnum = 40202 THEN
    PL_EXHIBIR_ERROR('El elemento no puede quedar en blanco!');
  ELSIF errnum = 40209 THEN
   PL_EXHIBIR_ERROR('Introduzca dígitos del 0 al 9 y coma(,) como separador decimal!');
  ELSIF errnum = 40301 THEN
    PL_EXHIBIR_ERROR('No se han encontrado registros para esta consulta. Presione <control> <u> para cancelar');
  ELSIF errnum = 40508 THEN
   --PL_EXHIBIR_ERROR('El codigo ya existe!');
    IF NVL(dbmserrnum,0) NOT IN(0,1017) THEN
      SET_ALERT_PROPERTY('AL_ERROR',ALERT_MESSAGE_TEXT,DBMS_ERROR_TEXT);
      V_ALERT := SHOW_ALERT('AL_ERROR');
      RAISE FORM_TRIGGER_FAILURE;
    ELSE
      RAISE FORM_TRIGGER_FAILURE;
    END IF;
  ELSIF errnum = 40600 THEN
    PL_EXHIBIR_ERROR('El registro ya ha sido ingresado previamente!');
  ELSIF errnum = 40602 THEN
    PL_EXHIBIR_ERROR('Dato no modificable!');
  ELSIF errnum = 41026 THEN
    --cuando se presiona flecha izq.o derecha sobre botones
    null;
  ELSIF errnum = 50016 THEN
    PL_EXHIBIR_ERROR('Introduzca dígitos del 0 al 9!');
  ELSIF errnum = 0060 AND errtyp = 'REP' THEN
    --OJO: esto no funciona porque el error ser produce a nivel del report y no del form
    PL_EXHIBIR_ERROR('No se puede imprimir o previsualizar este informe mientras está previsualizando otro!');
  ELSE
    MESSAGE(errtyp||'-'||TO_CHAR(errnum)||': '||errtxt);
    PAUSE;
  -- El error 1017 es cuando se ingresa mal el login/password.
    IF NVL(dbmserrnum,0) NOT IN(0,1017) THEN
      SET_ALERT_PROPERTY('AL_ERROR',ALERT_MESSAGE_TEXT,DBMS_ERROR_TEXT);
      V_ALERT := SHOW_ALERT('AL_ERROR');
      RAISE FORM_TRIGGER_FAILURE;
    ELSE
      RAISE FORM_TRIGGER_FAILURE;
    END IF;
  END IF;
END;

BEGIN
  IF :SYSTEM.MODE <> 'NORMAL' THEN
    EXIT_FORM;
  ELSE
    CLEAR_FORM(NO_VALIDATE, FULL_ROLLBACK);
    EXIT_FORM;
  END IF;
END;

:SYSTEM.MESSAGE_LEVEL := 10;
PL_WIN_MAXIMIZE('SISTEMA DE CONTROL DE STOCK','WINDOW0');
