BEGIN


  SELECT PERI_CODIGO INTO :BDOCU.W_PERIODO
    FROM "ADRE"."STK_PERIODO"
    WHERE :BDOCU.DOCU_FEC_EMIS BETWEEN
       PERI_FEC_INI AND PERI_FEC_FIN;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    PL_EXHIBIR_ERROR('No existe registro de periodo!');
  WHEN TOO_MANY_ROWS THEN
    PL_EXHIBIR_ERROR('Demasiados periodos encontrados!');
END;

BEGIN



BREAK;

  IF (NVL(:BDOCU.DOCU_GRAV_NETO_MON,0)
    + NVL(:BDOCU.DOCU_EXEN_NETO_MON,0)
    + NVL(:BDOCU.DOCU_IVA_MON,0)) > 0 THEN
        :BDOCU.W_TASA := ROUND((NVL(:BDOCU.DOCU_GRAV_NETO_LOC,0) +
                    NVL(:BDOCU.DOCU_EXEN_NETO_LOC,0) +
                    NVL(:BDOCU.DOCU_IVA_LOC,0)) /
                   (NVL(:BDOCU.DOCU_GRAV_NETO_MON,0) +
                    NVL(:BDOCU.DOCU_EXEN_NETO_MON,0) +
                    NVL(:BDOCU.DOCU_IVA_MON,0)),10);

  ELSE
    --:BDOCU.W_TASA := 0;
    :BDOCU.W_TASA := NVL(:BDOCU.DOCU_TASA_US,0) ;
  END IF;

  PP_DATOS_OPERACION;
  :BDOCU.W_MON := :BDOCU.DOCU_MON;
  :BDOCU.COMPROBANTE_REF :=  FP_DEVUELVE_NRO_FACT(:BDOCU.DOCU_CLAVE);
  :BDOCU.NRO_SOLICITUD   :=  FP_DEVUELVE_NRO_SOLICITUD(:BDOCU.DOCU_CLAVE);


  IF :BDOCU.W_IND_COSTO_VALOR = 'C' THEN
     /* para mostrar el costo en dolares en el bloque
        detalles */
     :BDOCU.W_MON_DEC_IMP := :PARAMETER.P_CANT_DEC_US;
     :BDOCU.S_MON_SIMBOLO := 'US$';
     :BDOCU.W_MON         := :PARAMETER.P_MON_US;

-- 02/03/1998 Esta funcion es muy pesada, mejor es acumular a medida
-- que va haciendo el post-query de cada registro.Luis Fedriani
-- :BDOCU.S_GRAV_NETO_MON := FP_COSTO_TOTAL;

  ELSE
     :BDOCU.S_GRAV_NETO_MON := :BDOCU.DOCU_GRAV_NETO_MON;
  END IF;






END;


IF :BDOCU.W_TASA > 0 THEN
  :BDETA.S_IMP_BRUTO_MON := :BDETA.DETA_IMP_BRUTO_LOC / :BDOCU.W_TASA;
  :BDETA.S_IMP_DTO_MON   := :BDETA.DETA_IMP_DTO_LOC / :BDOCU.W_TASA;
  :BDETA.S_IMP_GRAV_MON  := :BDETA.DETA_IMP_GRAV_LOC / :BDOCU.W_TASA;
  :BDETA.S_IMP_EXEN_MON  := :BDETA.DETA_IMP_EXEN_LOC / :BDOCU.W_TASA;
  :BDETA.S_IVA_MON       := :BDETA.DETA_IVA_LOC / :BDOCU.W_TASA;
ELSE
  :BDETA.S_IMP_BRUTO_MON := :BDETA.DETA_IMP_BRUTO_LOC;
  :BDETA.S_IMP_DTO_MON   := :BDETA.DETA_IMP_DTO_LOC;
  :BDETA.S_IMP_GRAV_MON  := :BDETA.DETA_IMP_GRAV_LOC;
  :BDETA.S_IMP_EXEN_MON  := :BDETA.DETA_IMP_EXEN_LOC;
  :BDETA.S_IVA_MON       := :BDETA.DETA_IVA_LOC;
END IF;

IF :PARAMETER.P_ART_ANTICIPO = :BDETA.DETA_ART THEN

	 SET_ITEM_INSTANCE_PROPERTY( 'BDETA.DETA_NRO_ITEM'  , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 
	 SET_ITEM_INSTANCE_PROPERTY( 'BDETA.DETA_ART'       , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 
	 SET_ITEM_INSTANCE_PROPERTY( 'BDETA.DETA_CANT'      , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 
	 SET_ITEM_INSTANCE_PROPERTY( 'BDETA.ART_DESC_ABREV' , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 
	 SET_ITEM_INSTANCE_PROPERTY( 'BDETA.DETA_PORC_DTO'  , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 

   SET_ITEM_INSTANCE_PROPERTY( 'BDETA.S_IMP_EXEN_MON' , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 
   SET_ITEM_INSTANCE_PROPERTY( 'BDETA.S_IMP_GRAV_MON' , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 
   SET_ITEM_INSTANCE_PROPERTY( 'BDETA.S_IVA_MON'      , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ;    

   SET_ITEM_INSTANCE_PROPERTY( 'BDETA.S_IMP_BRUTO_MON' , CURRENT_RECORD, VISUAL_ATTRIBUTE, 'VA_ROJO') ; 

END IF;

IF :BDOCU.W_IND_COSTO_VALOR = 'C' THEN
    PP_MOSTRAR_COSTO;
   :BDOCU.S_GRAV_NETO_MON := NVL(:BDOCU.S_GRAV_NETO_MON,0) + :BDETA.S_IMP_GRAV_MON;
END IF;

