DECLARE
  V_WHERE VARCHAR2(1000) := NULL;
  V_EXISTENCIA NUMBER;
BEGIN

IF :BSEL.W_CLAVE_RESPALDO IS NULL THEN	--- Solo si respaldo es nulo debe entrar


  set_item_property('BDOCU.COMPROBANTE_REF',VISIBLE,PROPERTY_TRUE);
  /*
  || construir la sentencia WHERE
  */
  PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_EMPR = '||TO_CHAR(:PARAMETER.P_EMPRESA) ,NULL);

  IF :BSEL.S_TIPO_MOV IS NOT NULL THEN
    PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_TIPO_MOV = '||TO_CHAR(:BSEL.S_TIPO_MOV), 'AND');
  END IF;

  IF :PARAMETER.P_COD_OPER IS NULL THEN
     IF :BSEL.S_CODIGO_OPERACION IS NOT NULL THEN
        PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_CODIGO_OPER = '||TO_CHAR(:BSEL.S_CODIGO_OPERACION), 'AND');
     END IF;
  ELSE
     PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_CODIGO_OPER = '||:PARAMETER.P_COD_OPER, 'AND');   	
  END IF;   	

  IF :PARAMETER.P_NRO_FACT IS NULL THEN 	
     IF :BSEL.S_NRO_DOC IS NOT NULL THEN
        PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_NRO_DOC = '||TO_CHAR(:BSEL.S_NRO_DOC), 'AND');
     END IF;
   ELSE  
     PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_NRO_DOC = '||:PARAMETER.P_NRO_FACT, 'AND');
   END IF;  

  IF :BSEL.S_PROV_CLIE IS NOT NULL THEN
    PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_PROV = '||TO_CHAR(:BSEL.S_PROV_CLIE), 'AND');
  END IF;

  IF :PARAMETER.P_DOCU_CLAVE IS NOT NULL THEN
    PP_CONSTRUIR_WHERE(V_WHERE,'DOCU_CLAVE = '||:PARAMETER.P_DOCU_CLAVE, 'AND');
  END IF;

  /*
  || establecer la propiedad DEFAULT_WHERE del bloque BDOCU
  || y ejecutar la consulta
  */

  SET_BLOCK_PROPERTY('BDOCU', DEFAULT_WHERE, V_WHERE);
  GO_BLOCK('BDOCU');
  EXECUTE_QUERY(ALL_RECORDS);


END IF;
    /* if :BSEL.S_CODIGO_OPERACION = 4 then 

    set_item_property('BDOCU.COMPROBANTE_REF',VISIBLE,PROPERTY_TRUE);

    else
  	/*sentencia para volver invisible el campo que referenciamos

    set_item_property('BDOCU.COMPROBANTE_REF',VISIBLE,PROPERTY_FALSE);



     END IF;*/

END;

DECLARE
  pl_id PARAMLIST;
  V_FORMATO VARCHAR2(20);
  SALIR EXCEPTION;

BEGIN
  IF FL_CONFIRMAR_REG('Desea emitir el listado?') <> 'CONFIRMAR' THEN
    RAISE SALIR;
  END IF;

  pl_id := GET_PARAMETER_LIST('ParamTemp');
  IF NOT ID_NULL(pl_id) THEN
     DESTROY_PARAMETER_LIST('ParamTemp');
  END IF;
  pl_id := CREATE_PARAMETER_LIST('ParamTemp');
  IF ID_NULL(pl_id) THEN
    PL_EXHIBIR_ERROR('Error al crear lista de parametros!');
  END IF;
  ADD_PARAMETER(pl_id,'P_EMPRESA',TEXT_PARAMETER,TO_CHAR(:PARAMETER.P_EMPRESA));
  ADD_PARAMETER(pl_id,'P_DESC_EMPRESA',TEXT_PARAMETER,:PARAMETER.P_DESC_EMPRESA);
  ADD_PARAMETER(pl_id,'P_DESC_PROGRAMA',TEXT_PARAMETER,:PARAMETER.P_DESC_PROGRAMA);
  ADD_PARAMETER(pl_id,'P_PROGRAMA',TEXT_PARAMETER,:PARAMETER.P_PROGRAMA);
  ADD_PARAMETER(pl_id,'P_DESC_SUCURSAL',TEXT_PARAMETER,:PARAMETER.P_DESC_SUCURSAL);
  ADD_PARAMETER(pl_id,'P_TIPO_MOV',TEXT_PARAMETER,TO_CHAR(:BSEL.S_TIPO_MOV));
  ADD_PARAMETER(pl_id,'P_TIPO_MOV_DESC',TEXT_PARAMETER,:BSEL.S_DESC_TIPO_MOV);
  ADD_PARAMETER(pl_id,'P_COD_OPER',TEXT_PARAMETER,TO_CHAR(:BSEL.S_CODIGO_OPERACION));
  ADD_PARAMETER(pl_id,'P_COD_OPER_DESC',TEXT_PARAMETER,:BSEL.S_DESC_OPER);
  ADD_PARAMETER(pl_id,'P_NRO_DOC',TEXT_PARAMETER,TO_CHAR(:BSEL.S_NRO_DOC));
  ADD_PARAMETER(pl_id,'P_PROV_CLIE',TEXT_PARAMETER,TO_CHAR(:BSEL.S_PROV_CLIE));
  ADD_PARAMETER(pl_id,'P_PROV_CLIE_NOMBRE',TEXT_PARAMETER,:BSEL.S_NOMBRE);
  ADD_PARAMETER(pl_id,'P_FEC_EMIS',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_FEC_EMIS,'DD-MM-YYYY'));
  ADD_PARAMETER(pl_id,'P_SUCURSAL_ORIG',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_SUC_ORIG));
  ADD_PARAMETER(pl_id,'P_SUCURSAL_ORIG_DESC',TEXT_PARAMETER,:BDOCU.S_DESC_SUCURSAL_ORIG);
  ADD_PARAMETER(pl_id,'P_DEPOSITO_ORIG',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_DEP_ORIG));
  ADD_PARAMETER(pl_id,'P_DEPOSITO_ORIG_DESC',TEXT_PARAMETER,:BDOCU.S_DESC_DEPOSITO_ORIG);
  ADD_PARAMETER(pl_id,'P_SUCURSAL_DEST',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_SUC_DEST));
  ADD_PARAMETER(pl_id,'P_SUCURSAL_DEST_DESC',TEXT_PARAMETER,:BDOCU.S_DESC_SUCURSAL_DEST);
  ADD_PARAMETER(pl_id,'P_DEPOSITO_DEST',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_DEP_DEST));
  ADD_PARAMETER(pl_id,'P_DEPOSITO_DEST_DESC',TEXT_PARAMETER,:BDOCU.S_DESC_DEPOSITO_DEST);
  ADD_PARAMETER(pl_id,'P_OPERADOR',TEXT_PARAMETER,:BDOCU.DOCU_LOGIN);
  ADD_PARAMETER(pl_id,'P_FEC_GRAB',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_FEC_GRAB,'DD-MM-YYYY'));
  ADD_PARAMETER(pl_id,'P_DEPARTAMENTO',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_DPTO));
  ADD_PARAMETER(pl_id,'P_DEPARTAMENTO_DESC',TEXT_PARAMETER,:BDOCU.S_DESC_DEPARTAMENTO);
  ADD_PARAMETER(pl_id,'P_SECCION',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_SECCION));
  ADD_PARAMETER(pl_id,'P_SECCION_DESC',TEXT_PARAMETER,:BDOCU.S_DESC_SECCION);
  ADD_PARAMETER(pl_id,'P_VENDEDOR',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_LEGAJO));
  ADD_PARAMETER(pl_id,'P_VENDEDOR_DESC',TEXT_PARAMETER,SUBSTR(:BDOCU.S_DESC_LEGAJO,1,20));
  ADD_PARAMETER(pl_id,'P_MONE_SIMBOLO',TEXT_PARAMETER,:BDOCU.S_MON_SIMBOLO);
  ADD_PARAMETER(pl_id,'P_SIST',TEXT_PARAMETER,:BDOCU.DOCU_SIST);
  ADD_PARAMETER(pl_id,'P_DOC_OBS',TEXT_PARAMETER,:BDOCU.S_DOCU_OBS);

  IF :BDOCU.DOCU_TASA_US IS NOT NULL THEN
  	ADD_PARAMETER(pl_id,'P_DOCU_TASA_US',TEXT_PARAMETER,:BDOCU.DOCU_TASA_US);  
  END IF;

  V_FORMATO := FP_FORMAT_MASK('BDOCU.DOCU_EXEN_NETO_MON', :BDOCU.W_MON_DEC_IMP);
  ADD_PARAMETER(pl_id,'P_EXEN_NETO_MON',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_EXEN_NETO_MON, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));
  ADD_PARAMETER(pl_id,'P_GRAV_NETO_MON',TEXT_PARAMETER,TO_CHAR(:BDOCU.S_GRAV_NETO_MON, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));
  ADD_PARAMETER(pl_id,'P_IVA_MON',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_IVA_MON, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));
  ADD_PARAMETER(pl_id,'P_DTO_MON',TEXT_PARAMETER,TO_CHAR(:BDOCU.S_DTO_MON, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));

  V_FORMATO := FP_FORMAT_MASK('BDOCU.DOCU_EXEN_NETO_LOC', :PARAMETER.P_CANT_DECIMALES_LOC);
  ADD_PARAMETER(pl_id,'P_EXEN_NETO_LOC',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_EXEN_NETO_LOC, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));
  ADD_PARAMETER(pl_id,'P_GRAV_NETO_LOC',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_GRAV_NETO_LOC, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));
  ADD_PARAMETER(pl_id,'P_IVA_LOC',TEXT_PARAMETER,TO_CHAR(:BDOCU.DOCU_IVA_LOC, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));
  ADD_PARAMETER(pl_id,'P_DTO_LOC',TEXT_PARAMETER,TO_CHAR(:BDOCU.S_DTO_LOC, V_FORMATO, 'NLS_NUMERIC_CHARACTERS = '',.'''));

  ADD_PARAMETER(pl_id,'P_TASA',TEXT_PARAMETER, TO_CHAR(:BDOCU.W_TASA));
  ADD_PARAMETER(pl_id,'P_PERIODO',TEXT_PARAMETER, TO_CHAR(:BDOCU.W_PERIODO));
  ADD_PARAMETER(pl_id,'P_DEC_IMP',TEXT_PARAMETER, TO_CHAR(:BDOCU.W_MON_DEC_IMP));
  ADD_PARAMETER(pl_id,'P_DETA_TIT1',TEXT_PARAMETER, :BSEL.W_DETA_TIT1);
  ADD_PARAMETER(pl_id,'P_DETA_TIT2',TEXT_PARAMETER, :BSEL.W_DETA_TIT2);
  ADD_PARAMETER(pl_id,'P_DETA_TIT3',TEXT_PARAMETER, :BSEL.W_DETA_TIT3);
  ADD_PARAMETER(pl_id,'P_DOCU_TIT1',TEXT_PARAMETER, :BSEL.W_DOCU_TIT1);
  ADD_PARAMETER(pl_id,'P_DOCU_TIT2',TEXT_PARAMETER, :BSEL.W_DOCU_TIT2);
  ADD_PARAMETER(pl_id,'P_DOCU_TIT3',TEXT_PARAMETER, :BSEL.W_DOCU_TIT3);
  ADD_PARAMETER(pl_id,'P_IND_COSTO_VALOR',TEXT_PARAMETER, :BDOCU.W_IND_COSTO_VALOR);
  ADD_PARAMETER(pl_id,'P_DOCU_IND_CONSIGNACION',TEXT_PARAMETER, :BDOCU.DOCU_IND_CONSIGNACION);

  ADD_PARAMETER(pl_id,'P_WHERE',TEXT_PARAMETER, 'DETA_CLAVE_DOC='||TO_CHAR(:BDOCU.DOCU_CLAVE));
  ADD_PARAMETER(pl_id,'PARAMFORM',TEXT_PARAMETER, 'NO');
  ADD_PARAMETER(pl_id,'DESTYPE',TEXT_PARAMETER, 'Preview');


  ADD_PARAMETER(pl_id,'DESFORMAT',TEXT_PARAMETER, FL_DESFORMAT);

	IF :BSEL.R_EXCEL = 'N' THEN	
  	RUN_PRODUCT(REPORTS,:PARAMETER.P_LISTADO,SYNCHRONOUS,RUNTIME,FILESYSTEM,pl_id,NULL);

	ELSE
  	RUN_PRODUCT(REPORTS,:PARAMETER.P_LISTADO2,SYNCHRONOUS,RUNTIME,FILESYSTEM,pl_id,NULL);		

	END IF;

EXCEPTION
  WHEN SALIR THEN
    NULL;
END;

BEGIN
  IF :SYSTEM.MODE = 'ENTER-QUERY' THEN
    EXIT_FORM; EXIT_FORM;
  END IF;
  IF :SYSTEM.MODE <> 'NORMAL' THEN
    EXIT_FORM;
  ELSE
    CLEAR_FORM(NO_VALIDATE, FULL_ROLLBACK);
    EXIT_FORM;
  END IF;
END;

DECLARE

  PL_ID PARAMLIST             ;
  V_FORMATO       VARCHAR2(20);
  SALIR           EXCEPTION   ;
  v_where         VARCHAR2(100);	


BEGIN	


IF NVL(:BSEL.S_CODIGO_OPERACION,0) != 3 THEN
	    PL_ME('Sólo se puede Re-Imprimir facturas de ventas emitidas.');
	ELSE
		IF :bdocu.docu_suc_orig != :parameter.p_sucursal then
			PL_ME('Sólo se puede Re-Imprimir facturas de su sucursal.');
		END IF;
END IF;		


	    --Preguntar si se desea imprimir el reporte...	
     if fl_confirmar_reg('Desea Re-imprimir la factura?') <> upper('confirmar') then
     	      raise salir;
     end if;

    SELECT ' AND DOC_CLAVE = '||TO_CHAR(DOC_CLAVE)
      INTO   v_where
      FROM   "ADRE"."FIN_DOCUMENTO"
    WHERE    DOC_CLAVE_STK  = :BDOCU.DOCU_CLAVE  ;




    ---Crear la lista de parametros 
  pl_id := get_parameter_list(upper('paramtemp'));
  if not id_null(pl_id) then
     destroy_parameter_list(upper('paramtemp'));
  end if;
  pl_id := create_parameter_list(upper('paramtemp'));
  if id_null(pl_id) then
    PL_ME('Error al crear lista de parametros!');
  end if;



  Add_parameter(pl_id,upper('desformat')         , text_parameter  , 'comprobante');  -- fl_desformat );
  Add_parameter(pl_id,upper('paramform')         , text_parameter  , 'no'); 
  Add_parameter(pl_id,upper('destype')           , text_parameter  , 'preview');
  --Add_Parameter(pl_id,upper('oracle_shutdown')   , text_parameter  , 'yes');  
  Add_Parameter(pl_id,upper('maximize')          , text_parameter  , 'yes');
  Add_Parameter(pl_id,upper('p_mostrar_msj_pie') , text_parameter  , upper('n'));  -- Se envia 'N' porque el mensaje del saldo del cliente pudo cambiar.
  Add_Parameter(pl_id,upper('p_mensaje_rese')    , text_parameter  , '  ');
  Add_Parameter(pl_id,upper('p_mensaje_resa')    , text_parameter  , '  '); 
  Add_Parameter(pl_id,upper('p_where')           , text_parameter  , v_where);  





  if :bdocu.docu_suc_orig = 28 then  	 
      run_product(reports,rtrim(ltrim(:parameter.reporte_rlux)), synchronous,runtime,filesystem,pl_id,null);
   else  
      run_product(reports,rtrim(ltrim(:parameter.reporte_resa)), synchronous,runtime,filesystem,pl_id,null);
  end if;


  Exception 	when no_data_found then 	pl_exhibir_error('Factura no existe en FINANZAS. Avise al Dpto. de Infórmatica.');

END;
